import pathlib,json,yaml,copy,hashlib,ipaddress,re,urllib.parse
def docs(path):
 value=[d for d in yaml.safe_load_all(pathlib.Path(path).read_text(encoding="utf8")) if d is not None]
 assert all(isinstance(d,dict) for d in value)
 ids=[(d.get("kind"),d.get("metadata",{}).get("namespace"),d.get("metadata",{}).get("name")) for d in value]
 assert len(ids)==len(set(ids)),"duplicate resources"
 return value
def canonical(value,key=None):
 if isinstance(value,dict):return {k:canonical(v,k) for k,v in value.items()}
 if isinstance(value,list):
  parts=[canonical(v) for v in value]
  if key in ("ports","containers","volumes","volumeMounts") and all(isinstance(v,dict) and isinstance(v.get("name"),str) for v in parts):
   assert len({v["name"] for v in parts})==len(parts),"duplicate named entries"
   return sorted(parts,key=lambda v:v["name"])
  return parts
 return value

def same(a,b):
 return json.dumps(canonical(a),sort_keys=True,separators=(",",":"))==json.dumps(canonical(b),sort_keys=True,separators=(",",":"))

